def conditional_put(connection,name,expected_etag,lease_id,body,now):
    if not isinstance(name,str) or not name or type(expected_etag) is not int or expected_etag<1 or not isinstance(lease_id,str) or not lease_id or not isinstance(body,bytes) or len(body)>65536 or type(now) is not int or now<0:raise ValueError('bounded typed write request')
    try:
        connection.execute('BEGIN IMMEDIATE')
        row=connection.execute('SELECT etag,lease_id,lease_until FROM blobs WHERE name=?',(name,)).fetchone()
        if row is None:raise KeyError(name)
        etag,current_lease,until=row
        if lease_id!=current_lease or until is None or now>=until:raise ValueError('active owned lease required')
        if etag!=expected_etag:raise ValueError('ETag precondition failed')
        connection.execute('UPDATE blobs SET body=?,etag=etag+1 WHERE name=?',(body,name));connection.commit()
        return etag+1
    except BaseException:
        connection.rollback()
        raise
