import json
def handshake(schema,method,headers,body,expected_topic,allowed_origin):
    values={key.lower():value for key,value in headers.items()}
    if schema=='cloudevents':
        if method!='OPTIONS':return 405,{},b''
        origin=values.get('webhook-request-origin')
        if origin!=allowed_origin:return 403,{},b''
        return 200,{'WebHook-Allowed-Origin':allowed_origin,'WebHook-Allowed-Rate':'120','Allow':'POST'},b''
    if schema!='eventgrid':raise ValueError('explicit configured schema required')
    if method!='POST':return 405,{},b''
    if values.get('aeg-event-type')!='SubscriptionValidation':return 400,{},b''
    try:
        events=json.loads(body)
        if not isinstance(events,list) or len(events)!=1:raise ValueError('single validation event')
        event=events[0]
        if not isinstance(event,dict):raise ValueError('event object required')
        if event.get('eventType')!='Microsoft.EventGrid.SubscriptionValidationEvent' or event.get('topic')!=expected_topic:raise ValueError('unexpected event or subscription topic')
        code=event['data']['validationCode']
        if not isinstance(code,str) or not 1<=len(code)<=128:raise ValueError('validation code')
    except (ValueError,KeyError,TypeError,UnicodeDecodeError):return 400,{},b''
    return 200,{'Content-Type':'application/json'},json.dumps({'validationResponse':code}).encode()
